package plangate

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
)

// PlannedCall is a single tool invocation the agent intends to execute.
type PlannedCall struct {
	ToolName           string
	Arguments          json.RawMessage
	TrustClassRequired []string
}

// PlannedActions is the full set of tool calls the agent plans to execute
// in a single turn.
type PlannedActions struct {
	Calls []PlannedCall
}

// Decision is the result of a plan gate safety check.
type Decision struct {
	Allowed      bool
	Reason       string
	BlockedCalls []string
}

// Gate checks planned tool calls before execution. Implementations
// must be safe for concurrent use.
type Gate interface {
	CheckPlan(ctx context.Context, plan PlannedActions) (Decision, error)
}

// Rule is a single safety check applied to each planned call.
type Rule interface {
	Check(ctx context.Context, call PlannedCall) (allowed bool, reason string)
}

// DefaultGate evaluates planned calls against a set of Rules. If any
// rule blocks a call, the entire plan is refused with details about which
// calls were blocked and why.
type DefaultGate struct {
	rules []Rule
}

// NewDefaultGate creates a plan gate with the TrustClassRule
// pre-registered. Additional rules can be added via AddRule.
func NewDefaultGate() *DefaultGate {
	return &DefaultGate{
		rules: []Rule{TrustClassRule{}},
	}
}

func (g *DefaultGate) AddRule(r Rule) {
	g.rules = append(g.rules, r)
}

func (g *DefaultGate) CheckPlan(ctx context.Context, plan PlannedActions) (Decision, error) {
	if len(plan.Calls) == 0 {
		return Decision{Allowed: true}, nil
	}

	var blocked []string
	var reasons []string

	for _, call := range plan.Calls {
		for _, rule := range g.rules {
			allowed, reason := rule.Check(ctx, call)
			if !allowed {
				blocked = append(blocked, call.ToolName)
				reasons = append(reasons, fmt.Sprintf("%s: %s", call.ToolName, reason))
				break
			}
		}
	}

	if len(blocked) > 0 {
		return Decision{
			Allowed:      false,
			Reason:       strings.Join(reasons, "; "),
			BlockedCalls: blocked,
		}, nil
	}

	return Decision{Allowed: true}, nil
}

// TrustClassRule blocks calls where the required trust class is not
// present in the caller's allowed roles.
type TrustClassRule struct{}

var allowedTrustClasses = map[string]bool{
	"operator":    true,
	"child-agent": true,
	"system":      true,
}

func (TrustClassRule) Check(ctx context.Context, call PlannedCall) (bool, string) {
	if len(call.TrustClassRequired) == 0 {
		return true, ""
	}

	for _, required := range call.TrustClassRequired {
		if !allowedTrustClasses[required] {
			return false, fmt.Sprintf("requires trust class %q which is not recognized", required)
		}
	}

	return true, ""
}

package toolgate

import (
	"context"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
)

type CallRequest struct {
	ToolName   string
	Arguments  json.RawMessage
	CallerRole string
}

type Decision struct {
	Allowed bool
	Reason  string
}

type Gate interface {
	CheckTool(ctx context.Context, call CallRequest) (Decision, error)
}

type DefaultGate struct {
	rules []Rule
}

type Rule interface {
	Check(ctx context.Context, call CallRequest) (allowed bool, reason string)
}

func NewDefaultGate() *DefaultGate {
	return &DefaultGate{
		rules: []Rule{
			IntentRule{},
			PermissionRule{},
		},
	}
}

func (g *DefaultGate) AddRule(r Rule) {
	g.rules = append(g.rules, r)
}

func (g *DefaultGate) CheckTool(ctx context.Context, call CallRequest) (Decision, error) {
	for _, rule := range g.rules {
		allowed, reason := rule.Check(ctx, call)
		if !allowed {
			return Decision{Allowed: false, Reason: reason}, nil
		}
	}
	return Decision{Allowed: true}, nil
}

type IntentRule struct{}

var blockedToolPatterns = []*regexp.Regexp{
	regexp.MustCompile(`rm\s+-rf\s+/`),
	regexp.MustCompile(`sudo\s+rm`),
	regexp.MustCompile(`chmod\s+777`),
	regexp.MustCompile(`curl.*\|.*sh`),
	regexp.MustCompile(`wget.*\|.*sh`),
}

func (IntentRule) Check(ctx context.Context, call CallRequest) (bool, string) {
	argsStr := strings.ToLower(string(call.Arguments))
	for _, pattern := range blockedToolPatterns {
		if pattern.MatchString(argsStr) {
			return false, fmt.Sprintf("tool call matches blocked pattern: %s", pattern.String())
		}
	}
	return true, ""
}

type PermissionRule struct{}

var systemOnlyTools = map[string]bool{
	"gateway_restart": true,
	"config_write":    true,
	"session_delete":  true,
}

func (PermissionRule) Check(ctx context.Context, call CallRequest) (bool, string) {
	if systemOnlyTools[call.ToolName] && call.CallerRole != "system" {
		return false, fmt.Sprintf("tool %q requires system role, caller is %q", call.ToolName, call.CallerRole)
	}
	return true, ""
}

package react

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/safety/plangate"
	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/safety/toolgate"
)

type RefuseAction struct {
	ToolName string
	Reason   string
}

type Decision struct {
	Action       string
	ToolCall     *plangate.PlannedCall
	Refusal      *RefuseAction
	ContinueTurn bool
}

type SafetyAdapter struct {
	planGate plangate.Gate
	toolGate toolgate.Gate
}

func NewSafetyAdapter(planGate plangate.Gate, toolGate toolgate.Gate) *SafetyAdapter {
	return &SafetyAdapter{planGate: planGate, toolGate: toolGate}
}

func (a *SafetyAdapter) CheckPlan(ctx context.Context, plan plangate.PlannedActions) (Decision, error) {
	decision, err := a.planGate.CheckPlan(ctx, plan)
	if err != nil {
		return Decision{}, err
	}
	if !decision.Allowed {
		return Decision{
			Action: "refuse",
			Refusal: &RefuseAction{
				ToolName: "plan",
				Reason:   decision.Reason,
			},
			ContinueTurn: true,
		}, nil
	}
	return Decision{Action: "proceed", ContinueTurn: true}, nil
}

func (a *SafetyAdapter) CheckTool(ctx context.Context, call toolgate.CallRequest) (Decision, error) {
	decision, err := a.toolGate.CheckTool(ctx, call)
	if err != nil {
		return Decision{}, err
	}
	if !decision.Allowed {
		return Decision{
			Action: "refuse",
			Refusal: &RefuseAction{
				ToolName: call.ToolName,
				Reason:   decision.Reason,
			},
			ContinueTurn: true,
		}, nil
	}
	return Decision{Action: "execute", ContinueTurn: true}, nil
}

type RefusalEvidence struct {
	ToolName string `json:"tool_name"`
	Reason   string `json:"reason"`
	Action   string `json:"action"`
}

func (r *RefuseAction) MarshalEvidence() (json.RawMessage, error) {
	ev := RefusalEvidence{
		ToolName: r.ToolName,
		Reason:   r.Reason,
		Action:   "refused",
	}
	b, err := json.Marshal(ev)
	if err != nil {
		return nil, fmt.Errorf("marshal refusal evidence: %w", err)
	}
	return b, nil
}

package safety

import "github.com/TrebuchetDynamics/gormes-agent/internal/llm/safety/plangate"

// PlannedCall is a single tool invocation the agent intends to execute.
type PlannedCall = plangate.PlannedCall

// PlannedActions is the full set of tool calls the agent plans to execute
// in a single turn.
type PlannedActions = plangate.PlannedActions

// PlanDecision is the result of a plan gate safety check.
type PlanDecision = plangate.Decision

// PlanGate checks planned tool calls before execution. Implementations
// must be safe for concurrent use.
type PlanGate = plangate.Gate

